270	// allows: a refusal must never come from a failed measurement, which is the rule
271	// `isLive` already keeps.
272	//
273	// An empty list allows too, and that took a second reading to see. The id being
274	// checked is this session's own, so a scan that found nobody found nobody
275	// *including the caller* — and this session is demonstrably running, because it
276	// is the one asking. `lib/live.js:124` states the same rule for the same
277	// directory: `readLive` returns `known: false` when the scan cannot see the
278	// session doing the scanning, and draws no conclusion from it. This drew one,
279	// and it gates every command, so the cost of being wrong was the whole plugin
280	// refusing to run with a message saying the id does not exist.
281	//
282	// What is fatal is a scan that found somebody else and not this id. That is the
283	// failure it was built for — an id off a background task's output directory,
284	// while real sessions were listed beside it.
285	//
286	// `clear <id>` and `adopt <id>` take the other session's id positionally rather
287	// than through `--session`, so a dead neighbour is still reachable — which is the
288	// whole point of those two commands.
289	function requireSession(opts) {
290	    const id = opts.session;
291	    if (!id) fail('--session <id> is required. The /fankeel prompt makes the hook say it; use that one.');
292	    if (!registry.sessionPath(process.cwd(), id)) fail('Not a session id: ' + id);
293	    const rows = live.runningSessions(live.liveConfigDir());
294	    if (rows && rows.length && !rows.some((row) => row.sessionId === id)) {
295	        const lines = ['No running Claude Code session has the id ' + id + '.', ''];
296	        lines.push('  running now:');
297	        for (const row of rows) lines.push('    ' + row.sessionId + (row.cwd ? '   ' + row.cwd : ''));
298	        lines.push('');
299	        lines.push('An entry written under that id is one no hook would ever read, and every');
300	        lines.push('hook is silent about a miss — so the mode would look on and do nothing.');
301	        lines.push('A path on screen carries a session id in the same shape and it is not');
302	        lines.push('always this one. The /fankeel prompt makes the hook say which it is.');
303	        fail(lines.join('\n'));
304	    }
305	    return id;
306	}
